<!--vbase-->
<template>
  <template v-if="show_button">
    <q-btn
      v-if="show_icon_btn"
      flat
      class="validation-view-button"
      @click="routeToAutoAccounting"
    >
      <Icon icon="mdi:calculator" width="24" height="24" />
      <q-tooltip>{{ $t('auto_accounting') }}</q-tooltip>
    </q-btn>
    <q-btn
      v-else
      flat
      :label="$t('auto_accounting')"
      color="primary"
      @click="routeToAutoAccounting"
    />

    <q-inner-loading :showing="show_loading" class="z-index-2">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </template>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';

import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { auto_accounting_setting } from 'src/constants';
import { toBoolPreference } from 'src/utils/preferenceBool';
import { useDocumentStore, useSettingStore } from 'src/store/main';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    show_icon_btn: {
      type: Boolean,
      default: true,
    },
  },
  components: {
    
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },

  methods: {
    initView() {
      if (!this.user_settings[this.auto_accounting_setting]) {
        this.user_settings[this.auto_accounting_setting] = false;
      }

      if (toBoolPreference(this.user_settings[this.auto_accounting_setting])) {
        this.show_button = true;
      }
    },

    async routeToAutoAccounting() {
      try {
        if (this.isReadOnly) {
          this.$router.push('/accounting/' + this.$route.params.id);
          return;
        }

        this.show_loading = true;
        const response: dynamicObj = await this.saveAndValidate();
        if (response.success === false) {
          const event = new CustomEvent('display_fields_errors', {});
          document.dispatchEvent(event);
          notify.error(response.message);
          return;
        }
        this.$router.push('/accounting/' + this.$route.params.id);
      } catch (err) {
        logError(err);
      } finally {
        this.show_loading = false;
      }
    },
  },
  data() {
    return {
      auto_accounting_setting,
    };
  },
  setup() {
    const doc_store = useDocumentStore();
    const { doc_loaded } = storeToRefs(doc_store);
    const { saveAndValidate } = doc_store;

    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    return {
      doc_loaded,
      user_settings,
      loading_settings,
      show_loading: ref(false),
      show_button: ref(false),
      saveAndValidate,
    };
  },
});
</script>
